// The caller posts { "items": [ ... ] }. n8n wraps a webhook body, so unwrap
// it once here. Everything else is left to the database, which is the only
// thing that knows which sources exist.
const body = $input.first().json.body || {};
const items = Array.isArray(body.items) ? body.items : null;

if (!items) {
  return [{ json: { items: '[]', count: 0,
                    error: 'Body must be JSON shaped { "items": [ ... ] }.' } }];
}
if (items.length > 200) {
  return [{ json: { items: '[]', count: items.length,
                    error: `Batch of ${items.length} items is too large. Send at most 200.` } }];
}
return [{ json: { items: JSON.stringify(items), count: items.length } }];

// One line per item the caller sent, in the order they sent them, so a caller
// can match answers to what it submitted without guessing.
const req = $('Read batch').first().json;

if (req.error) {
  return [{ json: { statusCode: 400, body: { error: req.error } } }];
}

const rows = $input.all().map(i => i.json).filter(r => r && r.url !== undefined);
const results = rows.map(r => r.accepted
  ? { url: r.url, accepted: true, item_id: r.item_id }
  : { url: r.url, accepted: false, reason: r.reason });

return [{ json: {
  statusCode: 200,
  body: {
    received: req.count,
    accepted: results.filter(r => r.accepted).length,
    rejected: results.filter(r => !r.accepted).length,
    results,
  },
}}];
